const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const hongKong = ee.Geometry.Point([114.1694, 22.3193]);
  const buffer = hongKong.buffer(30000); // 30km buffer around Hong Kong

  const period1Start = '2020-02-10';
  const period1End = '2020-02-26';
  const period2Start = '2020-04-20';
  const period2End = '2020-05-13';

  // 2. Data Acquisition & Check
  const no2Collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select('tropospheric_NO2_column_number_density');

  const col1 = no2Collection
    .filterDate(period1Start, period1End)
    .filterBounds(buffer);

  const col2 = no2Collection
    .filterDate(period2Start, period2End)
    .filterBounds(buffer);

  const size1 = await col1.size().getInfo();
  const size2 = await col2.size().getInfo();

  console.log(`Period 1 (Feb 10-25): ${size1} images`);
  console.log(`Period 2 (Apr 20-May 12): ${size2} images`);

  if (size1 === 0 || size2 === 0) {
    console.log("No data available for one or both periods.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing with quality masking
  function maskPoorQuality(image) {
    const qa = image.select('qa_value');
    const mask = qa.gte(0.75);
    return image.updateMask(mask);
  }

  // Apply quality mask and create mean composites
  const no2_1 = col1.map(maskPoorQuality).mean();
  const no2_2 = col2.map(maskPoorQuality).mean();

  // 4. Calculate mean NO2 and pixel counts
  const stats1 = await no2_1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: buffer,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = await no2_2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: buffer,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const mean1 = stats1.tropospheric_NO2_column_number_density_mean;
  const count1 = stats1.tropospheric_NO2_column_number_density_count;
  const mean2 = stats2.tropospheric_NO2_column_number_density_mean;
  const count2 = stats2.tropospheric_NO2_column_number_density_count;

  console.log(`Period 1: Mean NO2 = ${mean1}, Valid pixels = ${count1}`);
  console.log(`Period 2: Mean NO2 = ${mean2}, Valid pixels = ${count2}`);

  // 5. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log("No valid pixels after quality masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (mean1 === null || mean1 === undefined || mean2 === null || mean2 === undefined ||
      isNaN(mean1) || isNaN(mean2)) {
    console.log("Calculation failed - invalid results.");
    console.log("<answer>C3</answer>");
    return;
  }

  const percentChange = ((mean2 - mean1) / mean1 * 100).toFixed(2);
  console.log(`Change: ${percentChange}%`);

  if (mean2 > mean1) {
    console.log("NO2 levels increased from Feb to Apr-May period.");
    console.log("<answer>A</answer>");
  } else {
    console.log("NO2 levels did not increase.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
